/** 简单图标对象 → 只取 path/hex */
function ic(i: { hex: string; path: string }): IconData {
  return { hex: i.hex, path: i.path }
}

/** 服务显示名 → 归一化 slug（复用 ICONS 键） */
const SLUGS: Record<string, string> = {
  'google': 'google', 'youtube': 'youtube', 'github': 'github', 'cloudflare': 'cloudflare',
  'claude': 'claude', 'baidu': 'baidu', 'wechat': 'wechat',
  'npm': 'npm', 'docker hub': 'docker', 'apple': 'apple', 'vercel': 'vercel',
  'apple（国内）': 'apple', 'apple（海外）': 'apple', 'v2ex': 'v2ex',
  'chatgpt': 'chatgpt', '阿里云': 'aliyun', '腾讯云': 'tencent',
  '百度': 'baidu', '微信': 'wechat', 'gemini': 'gemini', 'grok': 'grok',
  '哔哩哔哩': 'bilibili',
}

/** 品牌标准色（显式写死，避免依赖 simple-icons 运行时 hex，确保白色图形始终有深色底纹可辨） */
const BRAND_COLORS: Record<string, string> = {
  'google': '#4285f4', 'youtube': '#ff0000', 'github': '#181717', 'cloudflare': '#f38020',
  'claude': '#d97757', 'baidu': '#2932e1', 'wechat': '#07c160',
  'npm': '#cb3837', 'docker': '#2496ed', 'apple': '#000000', 'vercel': '#000000',
  'aliyun': '#ff6a00', 'v2ex': '#043a52', 'chatgpt': '#10a37f', 'tencent': '#00a3ff',
  'gemini': '#4285f4', 'grok': '#000000', 'bilibili': '#00a1d6',
}

const props = defineProps<{ name: string }>()

const slug = computed(() => SLUGS[props.name.toLowerCase()] ?? '')
const icon = computed<IconData | null>(() => ICONS[slug.value] ?? null)
// 底纹统一用品牌色，浅色/深色主题都清晰可见：优先写死的品牌色，其次组件 hex，最后灰色兜底
const bgColor = computed(() => BRAND_COLORS[slug.value] ?? icon.value?.hex ?? '#64748b')
const iconStyle = computed(() => ({ backgroundColor: bgColor.value }))
const initial = computed(() => props.name.charAt(0).toUpperCase())
</script>

<template>
  <span
    class="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl shadow-sm"
    :style="iconStyle"
  >
    <svg v-if="icon" viewBox="0 0 24 24" width="20" height="20" role="img" aria-label="brand icon">
      <title>{{ name }}</title>
      <template v-if="icon.paths">
        <path v-for="(d, idx) in icon.paths" :key="idx" :d="d" fill="#ffffff" fill-rule="evenodd" />
      </template>
      <path v-else :d="icon.path!" fill="#ffffff" fill-rule="evenodd" clip-rule="evenodd" />
    </svg>
    <span v-else class="text-sm font-semibold text-white">{{ initial }}</span>
  </span>
</template>
